  coupon_id, coupon_name, coupon_amount,
  total_quantity, remaining_quantity,
  expire_time, redemption_code, status,coupon_type,min_order_amount
) VALUES (
           #{couponId}, #{couponName}, #{couponAmount},
           #{totalQuantity}, #{remainingQuantity},
           #{expireTime}, #{redemptionCode}, #{status},#{couponType},#{minOrderAmount}
         )

mapper.select:
SELECT coupon_id, coupon_name, coupon_amount, total_quantity, remaining_quantity, expire_time, redemption_code, status, coupon_type, min_order_amount, create_time, update_time FROM coupons
and coupon_name LIKE CONCAT('%', #{couponName}, '%')
and status = #{status}
and redemption_code = #{redemptionCode}
ORDER BY create_time DESC
